<script lang="ts">import type { EditorStore } from '../store.js'; import { reorderElement,setLocked,setVisibility } from '../commands.js'; export let editor:EditorStore;</script>
<section><h2>Layers</h2><ol>{#each [...$editor.document.elements].sort((a,b)=>b.zIndex-a.zIndex) as element (element.id)}<li class:selected={$editor.selection.has(element.id)}><button class="name" on:click={(e)=>editor.select([element.id],e.shiftKey)}>{element.type==='group'?'▾ ':''}{element.name}</button><button aria-label={element.visible?'Hide':'Show'} on:click={()=>editor.execute(setVisibility([element.id],!element.visible))}>{element.visible?'◉':'○'}</button><button aria-label={element.locked?'Unlock':'Lock'} on:click={()=>editor.execute(setLocked([element.id],!element.locked))}>{element.locked?'🔒':'♢'}</button><button aria-label="Raise" on:click={()=>editor.execute(reorderElement(element.id,'forward'))}>↑</button></li>{/each}</ol></section>
<style>section{padding:.75rem}h2{font-size:.8rem;text-transform:uppercase;letter-spacing:.08em}ol{list-style:none;padding:0;margin:0}li{display:flex;border-radius:var(--mble-radius-sm,4px)}.selected{background:var(--mble-selection,#f5c8b9)}.name{flex:1;text-align:left;overflow:hidden;text-overflow:ellipsis}</style>
